// ═══════════════════════════════════════════════════════════════
//  RSI Divergence Detector — V7 (engine CustomScript V7)
//  V2 — FIX: V1 pakai overlay() → garis RSI (0..100) dirender di chart
//       harga (~1.08) → di luar layar → kelihatan "tidak terjadi apa2".
//       RSI = oscillator → panel() sejak awal seharusnya.
//  Deteksi: pivot high/low RSI (kiri-kanan lb bars), bandingkan
//  2 pivot terakhir vs price → regular + hidden divergence.
//  Pattern V6.2: SEMUA var top-level, if/for hanya reassign. Nama ≤ 6.
// ═══════════════════════════════════════════════════════════════
panel()

// ── Parameters ──
len = 14      // RSI length
lb  = 5       // pivot lookback kiri/kanan
rng = 150     // max bar antara 2 pivot
isPH = 0      // flag pivot high (reassigned in scan)
isPL = 0      // flag pivot low  (reassigned in scan)

// ── Series dasar ──
r = rsi(close, len)

// ── Plot utama ──
plot(r, color=blue, style=style_line, width=2)
hline(70, color=red, style=style_dotted, width=1)
hline(50, color=gray, style=style_dotted, width=1)
hline(30, color=green, style=style_dotted, width=1)

// ── State (V6.2: top-level) ──
i     = bar_index
last  = i
pivH  = -1     // index pivot high RSI terakhir
pivH2 = -1     // pivot high sebelumnya
rH1   = 50.0   // RSI di pivH
rH2   = 50.0   // RSI di pivH2
pivL  = -1     // index pivot low RSI terakhir
pivL2 = -1     // pivot low sebelumnya
rL1   = 50.0
rL2   = 50.0
pHi1  = 0.0    // price high di pivH
pHi2  = 0.0
pLo1  = 0.0    // price low di pivL
pLo2  = 0.0

// ── Scan pivot (jalankan di bar terakhir saja — islast gate) ──
if islast:
    for j in range(lb, last - lb + 1):
        // pivot HIGH RSI: r[j] tertinggi vs lb kiri-kanan
        isPH = 1
        for k in range(1, lb + 1):
            if at(r, j) <= at(r, j - k): isPH = 0
            if at(r, j) <  at(r, j + k): isPH = 0
        if isPH:
            if j - pivH < rng:
                pivH2 = pivH
                rH2   = rH1
                pHi2  = pHi1
            pivH = j
            rH1  = at(r, j)
            pHi1 = at(high, j)
        // pivot LOW RSI: r[j] terendah vs lb kiri-kanan
        isPL = 1
        for k in range(1, lb + 1):
            if at(r, j) >= at(r, j - k): isPL = 0
            if at(r, j) >  at(r, j + k): isPL = 0
        if isPL:
            if j - pivL < rng:
                pivL2 = pivL
                rL2   = rL1
                pLo2  = pLo1
            pivL = j
            rL1  = at(r, j)
            pLo1 = at(low, j)

// ── Divergence lines ──
// REGULAR BEARISH: price HH + RSI LH
if pivH2 >= 0:
    if pHi1 > pHi2 and rH1 < rH2:
        line(pivH2, rH2, pivH, rH1, color=red, width=2, style=style_solid)
        label(pivH, rH1 + 4, "Bear Div", color=red, size=9)
// REGULAR BULLISH: price LL + RSI HL
if pivL2 >= 0:
    if pLo1 < pLo2 and rL1 > rL2:
        line(pivL2, rL2, pivL, rL1, color=green, width=2, style=style_solid)
        label(pivL, rL1 - 4, "Bull Div", color=green, size=9)
// HIDDEN BEARISH: price LH + RSI HH
if pivH2 >= 0:
    if pHi1 < pHi2 and rH1 > rH2:
        line(pivH2, rH2, pivH, rH1, color=orange, width=1, style=style_dashed)
        label(pivH, rH1 + 4, "H.Bear", color=orange, size=9)
// HIDDEN BULLISH: price HL + RSI LL
if pivL2 >= 0:
    if pLo1 > pLo2 and rL1 < rL2:
        line(pivL2, rL2, pivL, rL1, color=cyan, width=1, style=style_dashed)
        label(pivL, rL1 - 4, "H.Bull", color=cyan, size=9)

// ── Marker di panel: dot di tiap pivot terakhir ──
if pivH >= 0:
    dot(pivH, rH1, color=red, size=6)
if pivL >= 0:
    dot(pivL, rL1, color=green, size=6)
